package com.masterclass.inventory.service; import com.masterclass.inventory.dto.CategoryDtos.*; import com.masterclass.inventory.entity.Category; import com.masterclass.inventory.exception.*; import com.masterclass.inventory.mapper.CategoryMapper; import com.masterclass.inventory.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class CategoryService { private final CategoryRepository repo; private final CategoryMapper mapper; @Transactional public CategoryResponse create(CategoryRequest r){ if(repo.existsByNameIgnoreCase(r.name())) throw new BusinessException("Category exists"); return mapper.toResponse(repo.save(mapper.toEntity(r))); } @Transactional(readOnly=true) public List<CategoryResponse> list(){return repo.findAll().stream().map(mapper::toResponse).toList();} @Transactional public CategoryResponse update(Long id,CategoryRequest r){Category c=repo.findById(id).orElseThrow(()->new NotFoundException("Category not found")); c.setName(r.name()); c.setDescription(r.description()); return mapper.toResponse(c);} }
